import{_ as o,C as r,o as l,c as i,j as a,a as e,E as n,a5 as s}from"./chunks/framework.C1a7WKBV.js";const x=JSON.parse('{"title":"AI 工具选择器","description":"根据任务、基础、操作偏好与隐私要求，快速得到适合自己的 AI 软件起步组合。","frontmatter":{"title":"AI 工具选择器","description":"根据任务、基础、操作偏好与隐私要求，快速得到适合自己的 AI 软件起步组合。"},"headers":[],"relativePath":"tools/selector.md","filePath":"tools/selector.md","lastUpdated":1788838685000}'),h={name:"tools/selector.md"};function _(c,t,p,b,u,m){const d=r("ToolSelector");return l(),i("div",null,[t[0]||(t[0]=a("h1",{id:"ai-工具选择器",tabindex:"-1"},[e("AI 工具选择器 "),a("a",{class:"header-anchor",href:"#ai-工具选择器","aria-label":'Permalink to "AI 工具选择器"'},"​")],-1)),t[1]||(t[1]=a("p",null,[e("选工具先看任务、交互方式与数据边界，不先看热度。下面的选择器给出"),a("strong",null,"起步顺序"),e("，不是永久排名；产品功能与套餐会变化，实际信息以官网为准。")],-1)),t[2]||(t[2]=a("h2",{id:"_1-完成-60-秒选型",tabindex:"-1"},[e("1. 完成 60 秒选型 "),a("a",{class:"header-anchor",href:"#_1-完成-60-秒选型","aria-label":'Permalink to "1. 完成 60 秒选型"'},"​")],-1)),n(d),t[3]||(t[3]=s('<h2 id="_2-怎么理解推荐结果" tabindex="-1">2. 怎么理解推荐结果 <a class="header-anchor" href="#_2-怎么理解推荐结果" aria-label="Permalink to &quot;2. 怎么理解推荐结果&quot;">​</a></h2><h3 id="_2-1-第一名是主力工具" tabindex="-1">2.1 第一名是主力工具 <a class="header-anchor" href="#_2-1-第一名是主力工具" aria-label="Permalink to &quot;2.1 第一名是主力工具&quot;">​</a></h3><p>连续用它完成三个真实任务，记录成功率、返工次数、费用和你最常遇到的阻塞。不要在第一个任务失败后立刻换工具，先判断是模型、配置、提示词还是项目环境的问题。</p><h3 id="_2-2-第二名是备用路径" tabindex="-1">2.2 第二名是备用路径 <a class="header-anchor" href="#_2-2-第二名是备用路径" aria-label="Permalink to &quot;2.2 第二名是备用路径&quot;">​</a></h3><p>主力工具不支持某个场景时再启用。例如主力是图形编辑器，遇到大范围批量修改时再用终端 Agent；主力是云端模型，敏感资料改用本地模型。</p><h3 id="_2-3-第三名是进阶方向" tabindex="-1">2.3 第三名是进阶方向 <a class="header-anchor" href="#_2-3-第三名是进阶方向" aria-label="Permalink to &quot;2.3 第三名是进阶方向&quot;">​</a></h3><p>等主力工具形成稳定工作流后再学。多装一个工具不等于多一种能力，反而可能增加配置、订阅和上下文切换成本。</p><h2 id="_3-软件形态速查" tabindex="-1">3. 软件形态速查 <a class="header-anchor" href="#_3-软件形态速查" aria-label="Permalink to &quot;3. 软件形态速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>代表软件</th><th>优点</th><th>代价</th></tr></thead><tbody><tr><td>网页聊天</td><td>ChatGPT、Claude、Gemini、NotebookLM</td><td>零安装、功能综合</td><td>与本地文件和工程流程距离较远</td></tr><tr><td>AI 编辑器</td><td>Cursor、VS Code + Copilot</td><td>改动可见、上手平缓</td><td>大任务容易产生很多待审查修改</td></tr><tr><td>终端 Agent</td><td>Claude Code、Codex、Gemini CLI</td><td>能读项目、跑命令、自动验证</td><td>需要终端基础和权限意识</td></tr><tr><td>云端生成器</td><td>v0、Bolt、Lovable、Replit</td><td>原型快、可直接预览</td><td>迁移和深度定制可能受平台限制</td></tr><tr><td>本地模型</td><td>LM Studio、Ollama</td><td>数据边界清楚、离线可用</td><td>受内存、显存和本机性能限制</td></tr><tr><td>工作流平台</td><td>Dify、n8n、Coze</td><td>可连接数据和多个应用</td><td>需要维护流程、权限和失败重试</td></tr></tbody></table><h2 id="_4-选择前最后检查" tabindex="-1">4. 选择前最后检查 <a class="header-anchor" href="#_4-选择前最后检查" aria-label="Permalink to &quot;4. 选择前最后检查&quot;">​</a></h2><ol><li>官网是否明确支持你的操作系统和硬件。</li><li>免费额度是否足够完成一次完整试用，而不是只跑一句问答。</li><li>是否能导出数据、代码和配置，避免被单个平台锁定。</li><li>工作资料能否发送到该服务；不确定就先脱敏或使用本地方案。</li><li>是否有明确验证方式：测试、预览、引用、差异对比或人工审批。</li></ol><p>更完整的产品分类见《<a href="/ai-handbook/tools/overview">AI 工具全景图</a>》；决定编程形态见《<a href="/ai-handbook/tools/coding-tools">AI 编程工具怎么选</a>》。</p>',12))])}const A=o(h,[["render",_]]);export{x as __pageData,A as default};
